; Rosetta LFO (assembled after rosetta.asm; tables generated by tools/rosetta_build.py are appended after this).
;
; Every 2nd 5 ms tick (vector 0xC0 hook): phase += rate, wave -> value = base + depth * wave, written into the
; DSP-current program (RAM 0x41280). Sony's own driver diffs it against 0x41330 and sends the change to the DSPs,
; with Sony's own scaling. base = the edit buffer (RAM 0x458A0, what EDIT shows and SAVE stores), so saving never
; stores a modulated value. Writes only when the value changes; switching off puts the original back.
; Target = block A-F + its n-th editable parameter, found through Sony's EDIT page-set table (0x8044).

        .equ EDBUF, 0x58A0
        .equ CURBUF, 0x1280
        .equ EDTAB, 0x8044               ; 8 B per effect id: descriptor.w + 6-char name
        .equ SONY_TICK, 0x04FD           ; Sony's 5 ms tick handler (vector 0xC0)
        .equ L_VAR, RV+0x48              ; param_find results
        .equ L_MAX, RV+0x49
        .equ L_LABEL, RV+0x4A            ; word

; ---- vector 0xC0 points here ----
lfo_isr:
        STM.W   (R0-R5),@-SP
        STC.B   DP,R0
        MOV.W   R0,@-SP
        STC.B   EP,R0
        MOV.W   R0,@-SP
        JSR     @lfo_tick
        MOV.W   @SP+,R0
        LDC.B   R0,EP
        MOV.W   @SP+,R0
        LDC.B   R0,DP
        LDM.W   @SP+,(R0-R5)
        JMP     @SONY_TICK

lfo_tick:
        LDC.B   #4,DP
        LDC.B   #0,EP
        MOV.B   @L_TICK,R0               ; tick counter (live meter refresh rate)
        ADD.B   #1,R0
        MOV.B   R0,@L_TICK
        CMP.W   #MAGIC,@V_MAGIC
        BNE     lt_ret
        CMP.B   #SETVER,@V_VER
        BNE     lt_ret
        TST.B   @V_LFO_ON
        BNE     lt_on
        JMP     @lfo_release             ; off: put the last modulated byte back
lt_on:  MOV.B   @L_DIV,R1                ; every 2nd tick (~100 Hz)
        ADD.B   #1,R1
        AND.B   #1,R1
        MOV.B   R1,@L_DIV
        BNE     lt_ret
        CLR.W   R1                       ; phase += rate_tab[rate]
        MOV.B   @V_LFO_RATE,R1
        SHLL.W  R1
        MOV.W   R1,R4
        ADD.W   #rate_tab,R4
        MOV.W   @R4,R4
        MOV.W   @L_PHASE,R2
        ADD.W   R4,R2
        MOV.W   R2,@L_PHASE
        BCC     lt1
        MOV.W   @L_RND,R3                ; wrapped: next random value (16-bit LFSR)
        SHLR.W  R3
        BCC     lt0
        XOR.W   #0xB400,R3
lt0:    TST.W   R3
        BNE     lt0b
        MOV.W   #0xACE1,R3
lt0b:   MOV.W   R3,@L_RND
lt1:    SWAP.B  R2                       ; R2 = phase >> 8
        AND.W   #0x00FF,R2
        MOV.B   @V_LFO_WAVE,R0
        CMP.B   #0,R0
        BEQ     wv_tri
        CMP.B   #1,R0
        BEQ     wv_sin
        CMP.B   #2,R0
        BEQ     wv_sqr
        CMP.B   #3,R0
        BEQ     wv_saw
        MOV.W   @L_RND,R1                ; RANDOM (sample and hold per cycle)
        SWAP.B  R1
        AND.W   #0x00FF,R1
        SUB.W   #128,R1
        BRA     wv_done
wv_tri:  MOV.W   R2,R1                    ; -127 .. 127 .. -127
        SHLL.W  R1
        CMP.W   #256,R1
        BCS     wv_t1
        MOV.W   #510,R3
        SUB.W   R1,R3
        MOV.W   R3,R1
wv_t1:    SUB.W   #127,R1
        BRA     wv_done
wv_sin:  MOV.W   R2,R4
        ADD.W   #sine_tab,R4
        MOV.B   @R4,R1
        EXTS.B  R1
        BRA     wv_done
wv_sqr:  MOV.W   #127,R1
        CMP.W   #128,R2
        BCS     wv_done
        MOV.W   #0xFF81,R1               ; -127
        BRA     wv_done
wv_saw:  MOV.W   R2,R1
        SUB.W   #128,R1
wv_done: MOV.W   R1,@-SP                  ; signed wave
        CLR.W   R1
        MOV.B   @V_LFO_BLOCK,R1
        JSR     @blk_entry               ; R3 = block offset, R4 = EDIT entry (0 = none)
        MOV.W   R4,R4
        BEQ     lt_fail
        MOV.W   R3,@-SP
        CLR.W   R1
        MOV.B   @V_LFO_PARAM,R1
        JSR     @param_find
        MOV.W   @SP+,R3
        CMP.B   #0xFF,@L_VAR
        BEQ     lt_fail
        CLR.W   R0                       ; R0 = program offset of the target
        MOV.B   @L_VAR,R0
        ADD.W   R3,R0
        CMP.B   @L_LAST,R0
        BEQ     lt2
        MOV.W   R0,@-SP                  ; target changed: release the old one
        JSR     @lfo_release
        MOV.W   @SP+,R0
        MOV.B   R0,@L_LAST
lt2:    CLR.W   R2                       ; amp = depth * max / 200
        MOV.B   @V_LFO_DEPTH,R2
        CLR.W   R3
        MOV.B   @L_MAX,R3
        MULXU.B R3,R2
        DIVXU.B #200,R2
        AND.W   #0x00FF,R2
        MOV.W   @SP+,R1                  ; delta = wave * amp / 128
        MOV.W   R1,R3
        BPL     lt3
        NEG.W   R1
lt3:    MULXU.B R2,R1
        SHLR.W  R1
        SHLR.W  R1
        SHLR.W  R1
        SHLR.W  R1
        SHLR.W  R1
        SHLR.W  R1
        SHLR.W  R1
        TST.W   R3
        BPL     lt4
        NEG.W   R1
lt4:    MOV.W   R0,R2                    ; value = base + delta, clamp 0..max
        ADD.W   #EDBUF,R2
        CLR.W   R3
        MOV.B   @R2,R3
        ADD.W   R1,R3
        BPL     lt5
        CLR.W   R3
lt5:    CLR.W   R2
        MOV.B   @L_MAX,R2
        CMP.W   R2,R3
        BLE     lt6
        MOV.W   R2,R3
lt6:    MOV.W   R0,R2
        ADD.W   #CURBUF,R2
        CMP.B   @R2,R3
        BEQ     lt_ret                   ; unchanged: no DSP traffic
        MOV.B   R3,@R2
lt_ret: RTS
lt_fail:
        MOV.W   @SP+,R1
        JMP     @lfo_release

lfo_release:                             ; put the last modulated byte back (DP = 4)
        CLR.W   R0
        MOV.B   @L_LAST,R0
        CMP.B   #0xFF,R0
        BEQ     lr9
        MOV.W   R0,R2
        ADD.W   #EDBUF,R2
        MOV.B   @R2,R3
        MOV.W   R0,R2
        ADD.W   #CURBUF,R2
        MOV.B   R3,@R2
        MOV.B   #0xFF,@L_LAST
lr9:    RTS

; blk_entry: R1 = block 0..5 -> R3 = program offset, R4 = EDIT table entry (0 = none)   (DP=4, EP=0)
blk_entry:
        CMP.W   #6,R1
        BCC     be_bad
        MOV.W   R1,R4
        SHLL.W  R4
        SHLL.W  R4
        ADD.W   #blk_tab,R4
        CLR.W   R3
        MOV.B   @R4,R3                   ; program offset
        MOV.W   R3,R2
        ADD.W   #EDBUF+1,R2
        CLR.W   R1
        MOV.B   @R2,R1                   ; effect type (edit buffer)
        CMP.B   @(2,R4),R1               ; < number of types for this block?
        BCC     be_bad
        CLR.W   R2
        MOV.B   @(1,R4),R2               ; + EDIT id base
        ADD.W   R2,R1
        SHLL.W  R1
        SHLL.W  R1
        SHLL.W  R1
        ADD.W   #EDTAB,R1
        MOV.W   R1,R4
        RTS
be_bad: CLR.W   R4
        RTS

; param_find: R4 = EDIT entry, R1 = wanted index -> R3 = number of editable params,
;   L_VAR / L_MAX / L_LABEL of the wanted one (L_VAR = 0xFF if none). Editable = numeric slot, offset >= 2
;   (skips OnOff and TYPE).
param_find:
        MOV.B   #0xFF,@L_VAR
        MOV.W   @R4,R5                   ; descriptor
        CLR.W   R2
        MOV.B   @R5,R2                   ; pages
        MULXU.B #6,R2                    ; slots
        ADD.W   #8,R5
        CLR.W   R3
pf1:    MOV.W   @R5,R4                   ; slot type
        BPL     pf_next                  ; not numeric
        MOV.B   @(3,R5),R0               ; offset in the block
        CMP.B   #2,R0
        BCS     pf_next
        CMP.W   R1,R3
        BNE     pf_cnt
        MOV.B   R0,@L_VAR
        MOV.B   @(1,R5),R0
        MOV.B   R0,@L_MAX
        MOV.W   @(4,R5),R0
        MOV.W   R0,@L_LABEL
pf_cnt: ADD.W   #1,R3
pf_next:
        ADD.W   #8,R5
        SUB.W   #1,R2
        BNE     pf1
        RTS

; ---- K_DYN display routines for the MOD page ----
dyn_block:                               ; R1 = block -> "F HALL" in NAMEBUF (EP = 4), R2 = max 5
        MOV.W   R1,@-SP
        JSR     @blk_entry
        MOV.W   @SP+,R1
        MOV.W   #NAMEBUF,R0
        ADD.B   #0x41,R1                 ; 'A' + block
        MOV.B   R1,@R0+
        MOV.B   #0x20,@R0+
        MOV.W   R4,R4
        BEQ     db8
        ADD.W   #2,R4                    ; 6-char name, skip leading spaces
        MOV.B   #6,R2
db1:    MOV.B   @R4+,R1
        BEQ     db8
        CMP.B   #0x20,R1
        BNE     db2
        SUB.B   #1,R2
        BNE     db1
        BRA     db8
db2:    MOV.B   R1,@R0+
        MOV.B   @R4+,R1
        BEQ     db8
        SUB.B   #1,R2
        BNE     db2
db8:    CLR.B   @R0
        MOV.W   #NAMEBUF,R4
        LDC.B   #4,EP
        MOV.W   #5,R2
        RTS

dyn_param:                               ; R1 = param index -> its label (EP = 0), R2 = count - 1
        MOV.W   R1,@-SP
        CLR.W   R1
        MOV.B   @V_LFO_BLOCK,R1
        JSR     @blk_entry
        MOV.W   @SP+,R1
        MOV.W   R4,R4
        BEQ     dp_none
        JSR     @param_find
        MOV.W   R3,R2
        SUB.W   #1,R2
        BPL     dp1
        CLR.W   R2
dp1:    CMP.B   #0xFF,@L_VAR
        BEQ     dp_none2
        MOV.W   @L_LABEL,R4
        LDC.B   #0,EP
        RTS
dp_none:
        CLR.W   R2
dp_none2:
        MOV.W   #s_none,R4
        LDC.B   #0,EP
        RTS

s_none: .asciz  "---"
